import { z } from 'zod';
import { getConfigManager } from '../../services/ConfigManager';
import { IntegrationsClient } from '../../services/IntegrationsClient';
import { AuthenticatedReferenceProviderSchema } from '../../types/reference-connectors';
import { errorResult, okResult, type CliCommandResult } from '../envelope';

const COMMAND = 'profile.disconnect';

export const handleProfileDisconnect = async (
  positionals: string[],
): Promise<CliCommandResult> => {
  const selected = z
    .tuple([AuthenticatedReferenceProviderSchema])
    .safeParse(positionals);
  if (!selected.success)
    return errorResult(
      COMMAND,
      'USAGE_ERROR',
      'Usage: rivet profile disconnect <pinterest|arena|x>',
    );
  try {
    const config = getConfigManager();
    const accountId = config.getUserId();
    if (!accountId || !config.isAuthenticated())
      return errorResult(
        COMMAND,
        'AUTH_REQUIRED',
        'Sign in to Rivet before disconnecting a reference account.',
      );
    const provider = selected.data[0];
    const result = await new IntegrationsClient().disconnect(
      provider,
      accountId,
    );
    if (result.status === 'ok')
      return okResult(COMMAND, { provider, isDisconnected: true });
    if (config.getUserId() !== accountId)
      return errorResult(
        COMMAND,
        'OPERATION_FAILED',
        'Rivet account changed. Retry with the intended account.',
        { reason: 'account_changed' },
      );
    return errorResult(
      COMMAND,
      result.reason === 'auth_required' ? 'AUTH_REQUIRED' : 'OPERATION_FAILED',
      result.message,
      { reason: result.reason },
    );
  } catch {
    return errorResult(
      COMMAND,
      'OPERATION_FAILED',
      'Could not confirm reference account disconnection. Check your Rivet sign-in and connection, then retry.',
    );
  }
};
